def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict
    cache = OrderedDict()  # key -> [value, write_time]
    results = []

    def expire_if_needed(key, t):
        if key in cache:
            _, wt = cache[key]
            if t >= wt + ttl:
                del cache[key]

    for op in ops:
        kind = op[0]
        t = op[1]
        key = op[2]

        expire_if_needed(key, t)

        if kind == 'put':
            value = op[3]
            if key in cache:
                cache[key] = [value, t]
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = [value, t]
                cache.move_to_end(key)
        elif kind == 'get':
            if key in cache:
                value, wt = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                results.append(-1)

    return results

